    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
from collections import defaultdict
def solve(gi):
    H,W=len(gi),len(gi[0])
    sr=[r for r in range(H) if all(x==8 for x in gi[r])]
    sc=[c for c in range(W) if all(gi[r][c]==8 for r in range(H))]
    byc=defaultdict(list)
    for i in range(H):
        for j in range(W):
            v=gi[i][j]
            if v not in (0,8): byc[v].append((i,j))
    def blk(n,seps,nl):
        k=0;p=-1
        for s2 in seps+[nl]:
            if p<=n<s2: return k
            p=s2;k+=1
    def bnds(s,k,n):
        lo = s[k-1]+1 if k>0 else 0
        hi = s[k+1]-1 if k+1<len(s) else n-1
        return lo,hi
    cnt=defaultdict(set)
    for c,vs in byc.items():
        vs.sort()
        # adjacent same-color pairs along the same axis
        for a in range(len(vs)-1):
            (i1,j1),(i2,j2)=vs[a],vs[a+1]
            if j1==j2 and i1!=i2:  # vertical: paint whole column block, all row bands
                for br in range(H):
                    r0,r1=bnds(sr,br,H)
                    c0,c1=bnds(sc,blk(j1,sc,W),W)
                    for r in range(r0,r1+1):
                        for j in range(c0,c1+1): cnt[(r,j)].add(c)
            elif i1==i2 and j1!=j2:  # horizontal: paint whole row band, blocks spanned
                rk=blk(i1,sr,H)
                r0,r1=bnds(sr,rk,H)
                for cb in range(blk(j1,sc,W),blk(j2,sc,W)+1):
                    c0,c1=bnds(sc,cb,W)
                    for r in range(r0,r1+1):
                        for j in range(c0,c1+1): cnt[(r,j)].add(c)
    o=[[8 if (r in sr or j in sc) else 0 for j in range(W)] for r in range(H)]
    for r in range(H):
        for j in range(W):
            cs=cnt.get((r,j),set())
            if len(cs)>1: o[r][j]=6
            elif len(cs)==1: o[r][j]=list(cs)[0]
    return o
o=G['Demo pair 1 output']
r=solve(G['Demo pair 1 input'])
print('demo match:',r==o)
if r!=o:
    for i,(a,b) in enumerate(zip(r,o)):
        if a!=b: print(i,''.join(map(str,a)),'\n   ',''.join(map(str,b)))

